package com.mtgscanner.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.graphics.vector.group
import androidx.compose.ui.unit.dp

/** Magic symbols from the Mana font's SVGs (Andrew Gioia, SIL OFL 1.1), as icons for Icon(). */
object ManaIcons {
    private fun icon(name: String, w: Float, h: Float, vararg paths: String): ImageVector {
        val side = maxOf(w, h)
        return ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = side, viewportHeight = side)
            .apply {
                // Center non-square symbols so they aren't stretched.
                group(translationX = (side - w) / 2f, translationY = (side - h) / 2f) {
                    paths.forEach { addPath(addPathNodes(it), fill = SolidColor(Color.Black)) }
                }
            }.build()
    }

